/**
 * Performs a right node rotation.
 *
 * <p>After the rotation the left child of {@code node} becomes the new parent,
 * {@code node} becomes the right child of that new parent, and the right subtree
 * of the new parent (if any) becomes the left subtree of {@code node}.
 *
 * @param node a node to rotate
 * @return the new parent of {@code node}
 */
private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null || node.getLeft() == null) {
        // Nothing to rotate
        return node;
    }

    TreeNode<T> leftChild = node.getLeft();          // new parent
    TreeNode<T> leftRightSubtree = leftChild.getRight(); // subtree that will become left child of node

    // Perform rotation
    leftChild.setRight(node);          // node becomes right child of leftChild
    node.setLeft(leftRightSubtree);    // leftRightSubtree becomes left child of node

