/**
 * Retrieve the content length of the request.
 * @return The content length of the request, or {@code -1} if it cannot be determined.
 * @since 1.3
 */
public long contentLength() {
    // Prefer the servlet API method that returns a long (available since Servlet 3.1)
    long len = request.getContentLengthLong();
    if (len >= 0) {
        return len;
    }

    // Fallback: parse the "Content-Length" header manually
    String header = request.getHeader("Content-Length");
    if (header != null) {
        try {
            return Long.parseLong(header);
        } catch (NumberFormatException e) {
            // ignore and fall through to return -1
        }
    }

    // If we still can't determine the length, return -1
    return -1;
}

/**
 * Returns the index of the last directory separator character. <p>
 * This method will handle a file in either Unix or Windows format. The position of the last forward or backslash is returned. <p>
 * The output will be the same irrespective of the machine that the code is running on.
 *
 * @param filename  the filename to find the last path separator in, null returns -1
 * @return the index of the last separator character, or -1 if there is no such character
 */
public static int indexOfLastSeparator(String filename) {
    if (filename == null) {
        return -1;
    }

    // Find the last index of both separators
    int lastSlash = filename.lastIndexOf('/');
    int lastBackslash = filename.lastIndexOf('\\');

    // Return the maximum of the two (or -1 if both are -1)
    return Math.max(lastSlash, lastBackslash);
}

