/**
 * Searches for a byte of specified value in the {@code buffer}, starting at the specified {@code pos}.
 * @param value The value to find.
 * @param pos   The starting position for searching.
 * @return The position of byte found, counting from beginning of the {@code buffer}, or {@code -1} if not found.
 */
protected int findByte(byte value, int pos) {
    // If the starting position is out of bounds, we cannot find anything.
    if (pos < 0 || pos >= buffer.length) {
        return -1;
    }

    // Scan the buffer from the starting position to the end.
    for (int i = pos; i < buffer.length; i++) {
        if (buffer[i] == value) {
            return i; // Found the byte at index i.
        }
    }

    // Byte not found in the remaining part of the buffer.
    return -1;
}

