/**
 * Gets a substring from the specified String avoiding exceptions.
 *
 * @param str   the source string (may be {@code null})
 * @param start the starting index (inclusive)
 * @param end   the ending index (exclusive)
 * @return a substring of {@code str} from {@code start} to {@code end};
 *         if the parameters are out of bounds or {@code str} is {@code null},
 *         an empty string is returned
 */
public static String sub(String str, int start, int end) {
    if (str == null) {
        return "";
    }

    int len = str.length();

    // Clamp indices to valid range
    if (start < 0) {
        start = 0;
    }
    if (end > len) {
        end = len;
    }

    // If indices are still invalid, return empty string
    if (start >= end || start >= len) {
        return "";
    }

    return str.substring(start, end);
}

