/**
 * Computes a suffix sum of the {@code bounds}. Returns computed suffix sum and the sum of all elements in the {@code bounds list}.
 *
 * @param bounds list of integers.
 * @return computed pair of suffix sum list and a sum of all elements.
 */
private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // List to hold the suffix sums
    List<Integer> suffixSums = new ArrayList<>(bounds.size());

    // Compute the total sum of all elements
    long totalSum = 0L;

    // Compute suffix sums from the end of the list
    long runningSum = 0L;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        int value = bounds.get(i);
        runningSum += value;
        totalSum += value;
        // Insert at the beginning to maintain the original order
        suffixSums.add(0, (int) runningSum);
    }

    return new Pair<>(suffixSums, totalSum);
}

