    // If both are null, consider it a match
    if (str == null) {
        return prefix == null;
    }
    // If the prefix is null but the string is not, no match
    if (prefix == null) {
        return false;
    }

    // If the prefix is longer than the string, it cannot match
    if (prefix.length() > str.length()) {
        return false;
    }

    // Perform the comparison, optionally ignoring case
    if (ignoreCase) {
        // regionMatches with ignoreCase = true performs a case‑insensitive comparison
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    } else {
        return str.startsWith(prefix);
    }
}

