 */
public static boolean arrayequals(byte[] a, byte[] b, int count) {
    // If both references are the same, they are equal
    if (a == b) {
        return true;
    }
    // If either array is null, they cannot be equal
    if (a == null || b == null) {
        return false;
    }
    // If count is zero or negative, nothing to compare – treat as equal
    if (count <= 0) {
        return true;
    }
    // Ensure we don't read past the end of either array
    if (count > a.length || count > b.length) {
        return false;
    }
    // Compare byte by byte
    for (int i = 0; i < count; i++) {
        if (a[i] != b[i]) {
            return false;
        }
    }
    return true;
}

